[{"order":1,"type":"heading","text":"Understanding Parameter Resolution in JUnit 5"},{"order":2,"type":"paragraph","text":"JUnit 5 introduced the ParameterResolver extension API, a powerful mechanism that allows test constructors and methods to dynamically receive parameters at runtime. Unlike JUnit 4, which relied heavily on rigid runner architectures or Field-level injection, JUnit 5 uses dependency injection for test constructors and methods out of the box."},{"order":3,"type":"subheading","text":"What is the ParameterResolver API?"},{"order":4,"type":"paragraph","text":"The ParameterResolver interface defines the API for test extensions that wish to dynamically resolve parameters for lifecycle methods and test methods. By implementing this interface, you can tell JUnit how to instantiate complex objects and pass them directly into your test methods."},{"order":5,"type":"bullet_point","text":"supportsParameter: Determines if the resolver can handle a specific parameter context and extension context."},{"order":6,"type":"bullet_point","text":"resolveParameter: Performs the actual logic to supply the object instance for the requested parameter."},{"order":7,"type":"subheading","text":"Writing a Custom ParameterResolver"},{"order":8,"type":"paragraph","text":"To create a custom parameter resolver, implement the ParameterResolver interface and override both required methods. Below is an example of a resolver that injects a custom DatabaseConnection object based on a custom annotation."},{"order":9,"type":"code","text":"import org.junit.jupiter.api.extension.ExtensionContext;
import org.junit.jupiter.api.extension.ParameterContext;
import org.junit.jupiter.api.extension.ParameterResolver;
import java.lang.reflect.Parameter;

public class DatabaseConnectionResolver implements ParameterResolver {
    @Override
    public boolean supportsParameter(ParameterContext parameterContext, ExtensionContext extensionContext) {
        Parameter parameter = parameterContext.getParameter();
        return parameter.getType() == DatabaseConnection.class;
    }

    @Override
    public Object resolveParameter(ParameterContext parameterContext, ExtensionContext extensionContext) {
        return new DatabaseConnection("jdbc:h2:mem:testdb");
    }
}"},{"order":10,"type":"subheading","text":"Using the Resolver in Tests"},{"order":11,"type":"paragraph","text":"Once your resolver is created, you register it using the @ExtendWith annotation on your test class. JUnit will automatically invoke the resolver whenever a test method requests a parameter of that supported type."},{"order":12,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import static org.junit.jupiter.api.Assertions.assertNotNull;

@ExtendWith(DatabaseConnectionResolver.class)
class DatabaseTest {

    @Test
    void testDatabaseOperations(DatabaseConnection connection) {
        assertNotNull(connection);
        connection.connect();
    }
}"},{"order":13,"type":"subheading","text":"Best Practices for Parameter Resolution"},{"order":14,"type":"bullet_point","text":"Keep resolvers stateless or thread-safe if tests run in parallel."},{"order":15,"type":"bullet_point","text":"Always check parameter types explicitly in supportsParameter to avoid unintended injections."},{"order":16,"type":"bullet_point","text":"Combine resolvers with custom annotations to target specific injections gracefully."}]
